<script setup>import {reactive,ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const form=reactive({name:'',place:'',owner:'应急保障组'}),note=ref(''),msg=ref('');const act=f=>{const r=f();msg.value=r.message||(r.ok?'操作成功':'操作失败')};</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">演</div><div><h2>演练管理</h2><p>创建、启动、评估和归档演练</p></div></div><article class="panel"><div class="button-row"><input v-model="form.name" placeholder="演练名称"><input v-model="form.place" placeholder="演练地点"><button class="primary-button active" @click="act(()=>actions.createDrill(form))">创建演练</button></div></article><p v-if="msg" class="action-message">{{msg}}</p><article v-for="d in state.drills" :key="d.id" class="panel"><header><div><h3>{{d.name}}</h3><small>{{d.id}} · {{d.place}} · {{d.owner}}</small></div><strong>{{d.status}}</strong></header><p v-if="d.result">执行结果：{{d.result}}</p><p v-if="d.evaluation">评估结论：{{d.evaluation}}</p><div class="button-row"><button v-if="['计划中','待启动'].includes(d.status)" class="primary-button active" @click="act(()=>actions.startDrill(d.id))">启动演练</button><input v-if="d.status==='待评估'||d.status==='执行中'" v-model="note" :placeholder="d.status==='执行中'?'填写执行结果':'填写评估结论'"><button v-if="d.status==='执行中'" class="secondary-button" @click="act(()=>actions.submitDrill(d.id,note))">提交执行结果</button><button v-if="d.status==='待评估'" class="secondary-button" @click="act(()=>actions.evaluateDrill(d.id,note))">完成评估</button></div></article></section></template>
